@Configuration
public class ChannelsConfig {
    @Bean MessageChannel ordersDirect() { return new DirectChannel(); }      // sync, транзакция насквозь
    @Bean MessageChannel ordersQueue()  { return new QueueChannel(1000); }   // async, нужен Poller

    @Bean
    public IntegrationFlow asyncFlow(OrderService service, PlatformTransactionManager tm) {
        return IntegrationFlow
            .from("ordersQueue",
                c -> c.poller(Pollers.fixedDelay(100)
                    .transactional(tm)            // транзакция стартует на каждом poll-tick
                    .maxMessagesPerPoll(10)))
            .handle(service::process)
            .get();
    }
}
